// .anasakiignore: a gitignore-lite matcher. Supported: blank lines and
// "#" comments, globs (* ? ** [abc]), a trailing "/" (folders only), a leading
// "/" or an inner "/" (anchored to the sync folder, else matched at any depth),
// and "!" to re-include. Paths are always "/"-separated and relative.

// Always ignored, before the user's rules. Dotfiles and dot-folders cover
// .git, .anasaki (sync state), .vscode, .DS_Store, ...
export const BUILTIN_RULES = [
  '.*',
  'node_modules/',
  'anasaki.json',
  '.anasakiignore',
  '/anasaki.d.ts', // generated by `pull` / `types`
  '/tsconfig.json', // written by `init` for VS Code
  '/jsconfig.json',
];

export const SYNC_EXTENSIONS = ['.ts', '.js', '.mjs', '.json', '.md'];

function globToRegex(glob) {
  let re = '';
  for (let i = 0; i < glob.length; i++) {
    const c = glob[i];
    if (c === '*') {
      if (glob[i + 1] === '*') {
        const prevSlash = i === 0 || glob[i - 1] === '/';
        const nextSlash = glob[i + 2] === '/';
        if (prevSlash && nextSlash) { re += '(?:.*/)?'; i += 2; continue; }
        if (prevSlash && i + 2 === glob.length) { re += '.*'; i += 1; continue; }
        re += '.*'; i += 1; continue;
      }
      re += '[^/]*';
    } else if (c === '?') {
      re += '[^/]';
    } else if (c === '[') {
      const end = glob.indexOf(']', i + 1);
      if (end < 0) { re += '\\['; continue; }
      let cls = glob.slice(i + 1, end).replace(/\\/g, '\\\\');
      if (cls.startsWith('!')) cls = '^' + cls.slice(1);
      re += '[' + cls + ']';
      i = end;
    } else if (c === '\\' && i + 1 < glob.length) {
      re += '\\' + glob[++i];
    } else {
      re += c.replace(/[.+^${}()|\\/]/g, '\\$&');
    }
  }
  return re;
}

export function parseRule(line) {
  let s = line.replace(/\r$/, '');
  if (!s.trim() || s.startsWith('#')) return null;
  s = s.replace(/(?<!\\)\s+$/, ''); // trailing spaces
  let neg = false;
  if (s.startsWith('!')) { neg = true; s = s.slice(1); }
  if (s.startsWith('\\#') || s.startsWith('\\!')) s = s.slice(1);
  let dirOnly = false;
  if (s.endsWith('/')) { dirOnly = true; s = s.replace(/\/+$/, ''); }
  if (!s) return null;
  let anchored = s.includes('/');
  if (s.startsWith('/')) s = s.slice(1);
  if (s.startsWith('**/')) anchored = true; // the glob itself matches any depth
  const body = globToRegex(s);
  const re = new RegExp('^' + (anchored ? '' : '(?:.*/)?') + body + '$');
  return { neg, dirOnly, re, source: line };
}

export function createIgnore(userText = '', { builtins = true } = {}) {
  const rules = [];
  if (builtins) for (const r of BUILTIN_RULES) rules.push(parseRule(r));
  for (const line of String(userText).split('\n')) {
    const r = parseRule(line);
    if (r) rules.push(r);
  }
  const test = (p, isDir) => {
    let ignored = false;
    for (const r of rules) {
      if (r.dirOnly && !isDir) continue;
      if (r.re.test(p)) ignored = !r.neg;
    }
    return ignored;
  };
  return {
    rules,
    /** ignores reports whether a "/"-separated relative path is ignored. */
    ignores(relPath, isDir = false) {
      const p = String(relPath).replace(/\\/g, '/').replace(/^\.\/+/, '').replace(/\/+$/, '');
      if (!p) return false;
      const parts = p.split('/');
      // an ignored parent folder cannot be re-included (like git)
      for (let i = 1; i < parts.length; i++) {
        if (test(parts.slice(0, i).join('/'), true)) return true;
      }
      return test(p, isDir);
    },
  };
}

export function hasSyncExtension(p) {
  const m = /\.[^./]+$/.exec(p);
  return !!m && SYNC_EXTENSIONS.includes(m[0].toLowerCase());
}

const SEGMENT = /^[A-Za-z0-9._-]+$/;

/** validRemotePath mirrors the server's path rules (sitecode.ValidPath). */
export function validRemotePath(p) {
  if (!p || p.length > 255 || p.startsWith('/') || p.includes('\\')) return false;
  return p.split('/').every((s) => s && s !== '.' && s !== '..' && SEGMENT.test(s));
}
